def main():
    path=RESEARCH/'sources.json';data=json.loads(path.read_text());items={s['id']:s for s in data['sources']}
    for sid,url,title,publisher,version,section,passage,population,limits,cache,depth in READS:
        item={'id':sid,'url':url,'titre':title,'editeur':publisher,'version_annee':version,'date_consultation':'2026-11-02','section_page':section,'passage_paraphrase':passage,'population':population,'limites':limits,'niveau_lecture':depth,'read_in_current_session':True}
        if cache:item['cache_sha256']=hashlib.sha256((CACHE/cache).read_bytes()).hexdigest()
        else:item['proof_mode']='Passage consulté dans outil web ; aucun hash de fichier local prétendu.'
        items[sid]=item
    items['S101']['section_page']+=' ; §4.4.1,4.4.3,5.1,5.2.3,6.1.2'
    items['S102']['section_page']+=' ; fréquences, IPI et limites'
    items['S104']['section_page']+=' ; fréquences différentielles et association myasthénie'
    for sid in ['S108','S110','S111']:items[sid]['section_page']+=' ; aptitude à la conduite'
    items['S110']['passage_paraphrase']+=' Dose cible2×10⁶cellules/kg,max2×10⁸ ; conduite au moins2semaines et disparition des effets neurologiques.'
    data['sources']=list(items.values());data['source_count']=len(items);data['recorded_at']=datetime.datetime.now(datetime.timezone.utc).isoformat()
    data['historical_sources']='23références héritées conservées avec leur provenance ; lectures nouvelles ciblées décrites individuellement, pas prétention de lecture intégrale de tous les articles.'
    path.write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
    print(json.dumps({'sources':len(items),'medical_review_automated':False}))
if __name__=='__main__':main()
